/* Linux sources for the fields generated by the original DeviceInfo.cpp.
 * Serial-number format: H/B/G/N source markers followed by uppercase SHA-256
 * of the first two available disk/BIOS/machine-ID/hostname identifiers.
 * No Windows registry, Wine profile, or login keystore is read or modified. */
#define _DEFAULT_SOURCE
#define _POSIX_C_SOURCE 200809L
#include "login_security_identity.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <cpuid.h>
#include <ifaddrs.h>
#include <net/if.h>
#include <netpacket/packet.h>
#include <sys/sysmacros.h>
#include <limits.h>
#include <ctype.h>
#include <openssl/evp.h>

static void login_read_identifier(const char *path, char *out, size_t size)
{
    out[0] = 0;
    FILE *f = fopen(path,"r");
    if (!f) return;
    if (!fgets(out,(int)size,f)) out[0] = 0;
    fclose(f);
    size_t n = strlen(out);
    while (n && isspace((unsigned char)out[n-1])) out[--n] = 0;
}

static void login_device_item(struct json_object *array, const char *type, const char *value)
{
    if (!*value) return;
    struct json_object *o = json_object_new_object();
    json_object_object_add(o,"deviceType",json_object_new_string(type));
    json_object_object_add(o,"deviceValue",json_object_new_string(value));
    json_object_array_add(array,o);
}

void login_security_disk_serial(char *out, size_t capacity)
{
    if (!out || !capacity) return;
    out[0] = 0;
    if (capacity>INT_MAX) capacity=INT_MAX;
    char path[PATH_MAX], resolved[PATH_MAX];
    struct stat root;
    if (!stat("/",&root)) {
        snprintf(path,sizeof(path),"/sys/dev/block/%u:%u",major(root.st_dev),minor(root.st_dev));
        if (realpath(path,resolved)) {
            if (strlen(resolved)+15 < sizeof(path)) {
                snprintf(path,sizeof(path),"%s/device/serial",resolved);
                login_read_identifier(path,out,capacity);
            }
            if (!*out) {
                char *slash = strrchr(resolved,'/');
                if (slash) {
                    *slash = 0;
                    if (strlen(resolved)+15 < sizeof(path)) {
                        snprintf(path,sizeof(path),"%s/device/serial",resolved);
                        login_read_identifier(path,out,capacity);
                    }
                }
            }
        }
    }
}

int login_security_identity(struct json_object **info, char serial[67])
{
    char disk[256] = "", bios[256], guid[256], name[256], cpu[17] = "";
    login_security_disk_serial(disk,sizeof(disk));
    login_read_identifier("/sys/class/dmi/id/product_serial",bios,sizeof(bios));
    login_read_identifier("/etc/machine-id",guid,sizeof(guid));
    if (gethostname(name,sizeof(name))) name[0] = 0;
    name[sizeof(name)-1] = 0;
    const char *ids[] = {disk,bios,guid,name};
    const char marks[] = "HBGN";
    EVP_MD_CTX *digest = EVP_MD_CTX_new();
    if (!digest || EVP_DigestInit_ex(digest,EVP_sha256(),NULL)!=1) {
        EVP_MD_CTX_free(digest); return ENOMEM;
    }
    size_t count = 0;
    for (size_t i=0;i<4 && count<2;i++) if (*ids[i]) {
        serial[count++] = marks[i];
        if (EVP_DigestUpdate(digest,ids[i],strlen(ids[i]))!=1) {
            EVP_MD_CTX_free(digest); return EIO;
        }
    }
    unsigned char hash[32]; unsigned hash_size = 0;
    if (!count || EVP_DigestFinal_ex(digest,hash,&hash_size)!=1 || hash_size!=32) {
        EVP_MD_CTX_free(digest); return ENODEV;
    }
    EVP_MD_CTX_free(digest);
    for (size_t i=0;i<32;i++) snprintf(serial+count+i*2,3,"%02X",hash[i]);
    if (!info) return 0;
    *info = json_object_new_array();
    if (!*info) return ENOMEM;
    struct ifaddrs *interfaces = NULL;
    if (!getifaddrs(&interfaces)) {
        for (struct ifaddrs *p=interfaces;p;p=p->ifa_next) {
            if (!p->ifa_addr || p->ifa_addr->sa_family!=AF_PACKET || (p->ifa_flags&IFF_LOOPBACK)) continue;
            const struct sockaddr_ll *a = (const struct sockaddr_ll *)p->ifa_addr;
            if (a->sll_halen!=6) continue;
            char mac[18];
            snprintf(mac,sizeof(mac),"%02X-%02X-%02X-%02X-%02X-%02X",a->sll_addr[0],a->sll_addr[1],
                     a->sll_addr[2],a->sll_addr[3],a->sll_addr[4],a->sll_addr[5]);
            login_device_item(*info,"MAC",mac);
        }
        freeifaddrs(interfaces);
    }
    unsigned eax,ebx,ecx,edx;
    if (__get_cpuid(1,&eax,&ebx,&ecx,&edx)) snprintf(cpu,sizeof(cpu),"%08X%08X",edx,eax);
    login_device_item(*info,"CPUID",cpu);
    login_device_item(*info,"GUID",guid);
    login_device_item(*info,"serialNumber",serial);
    return 0;
}

void login_security_mask_uuid(const char *serial, char *out, size_t capacity)
{
    size_t n=strlen(serial);
    if (!capacity) return;
    if (n>=capacity) { out[0]=0; return; }
    memcpy(out,serial,n+1);
    size_t keep=n>=4 ? n/4 : 0;
    memset(out+keep,'*',n-keep*2);
}
